class Solution:
    def removeAlmostEqualCharacters(self, word: str) -> int:
        n = len(word)
        INF = 10**9

        prev = [INF] * 26
        first = ord(word[0]) - ord('a')
        for c in range(26):
            prev[c] = 0 if c == first else 1

        for i in range(1, n):
            curr = [INF] * 26
            original = ord(word[i]) - ord('a')
            for c in range(26):
                cost = 0 if c == original else 1
                best = INF
                for pc in range(26):
                    if abs(c - pc) > 1:
                        best = min(best, prev[pc])
                curr[c] = best + cost
            prev = curr

        return min(prev)
